#!/bin/bash
# Builds the user documentation into release/site_docs.
# Usage: ./build-docs.sh [--serve]
#
# The reference pages in docs/reference/ are generated by opensloper-cli doc
# from the program itself. They are committed, so the site builds without a
# Pascal toolchain (as the GitHub Pages workflow does); this script writes
# them again first when release/opensloper-cli has been built.
set -e
cd "$(dirname "$0")"

CLI=release/opensloper-cli

if [ -x "$CLI" ]; then
  for topic in $("$CLI" doc); do
    "$CLI" doc "$topic" -o "docs/reference/$topic.md"
  done
else
  echo "Note: $CLI is not built, so docs/reference/ is left as it is (run ./build.sh first)"
fi

if [ "$1" = "--serve" ]; then
  ./venv/bin/zensical serve
else
  ./venv/bin/zensical build --clean --strict
fi
